int kart_can_control_pack(
    uint8_t *dst_p,
    const struct kart_can_control_t *src_p,
    size_t size)
{
    if (size < 3u) {
        return (-EINVAL);
    }

    memset(&dst_p[0], 0, 3);

    dst_p[0] |= pack_left_shift_u8(src_p->etc_mode, 0u, 0xffu);
    dst_p[1] |= pack_left_shift_u8(src_p->launch_active, 0u, 0xffu);
    dst_p[2] |= pack_left_shift_u8(src_p->auto_shift, 0u, 0xffu);

    return (3);
}

int kart_can_control_unpack(
    struct kart_can_control_t *dst_p,
    const uint8_t *src_p,
    size_t size)
{
    if (size < 3u) {
        return (-EINVAL);
    }

    dst_p->etc_mode = unpack_right_shift_u8(src_p[0], 0u, 0xffu);
    dst_p->launch_active = unpack_right_shift_u8(src_p[1], 0u, 0xffu);
    dst_p->auto_shift = unpack_right_shift_u8(src_p[2], 0u, 0xffu);

    return (0);
}

int kart_can_control_init(struct kart_can_control_t *msg_p)
{
    if (msg_p == NULL) return -1;

    memset(msg_p, 0, sizeof(struct kart_can_control_t));

    return 0;
}

